/// Escape `%`, `_`, and `\\` in `input` for safe use inside a `LIKE`/`ILIKE`
/// pattern with `ESCAPE '\\'`, so a caller's literal wildcard-looking
/// characters (most commonly `_` in a repository name) match themselves
/// rather than acting as pattern metacharacters.
pub fn escape_like_pattern(input: &str) -> String {
    input
        .replace('\\', "\\\\")
        .replace('%', "\\%")
        .replace('_', "\\_")
}

impl FleetStore {
    /// Connect to the Ackplane read models needed for Fleet queries.
    pub async fn connect(database_url: &str) -> Result<Self, tokio_postgres::Error> {
        let (mut client, connection) = tokio_postgres::connect(database_url, NoTls).await?;
        tokio::spawn(async move {
            if let Err(error) = connection.await {
                tracing::error!(%error, "ackplane fleet connection closed with an error");
            }
        });
        crate::migration_lock::migrate_locked(
            &mut client,
            crate::migration_lock::key::ENROLLMENT,
            ENROLLMENT_MIGRATION,
        )
        .await?;
        crate::migration_lock::migrate_locked(
            &mut client,
            crate::migration_lock::key::PROJECTION,
            PROJECTION_MIGRATION,
        )
        .await?;
        crate::migration_lock::migrate_locked(
            &mut client,
            crate::migration_lock::key::LEDGER,
            LEDGER_MIGRATION,
        )
        .await?;
        crate::migration_lock::migrate_locked(
            &mut client,
            crate::migration_lock::key::CLAIM_DELEGATION,
            CLAIM_MIGRATION,
        )
        .await?;
        crate::migration_lock::migrate_locked(
            &mut client,
            crate::migration_lock::key::SIGNING_KEYS,
            SIGNING_KEYS_MIGRATION,
        )
        .await?;
        Ok(Self { client })
    }
}

